
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b3p86_nwchem_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b3p86_nwchem", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.547389297106867e+00, -3.480885294681689e+00, -3.387731840153203e+00, -3.258764887547120e+00, -3.083188775688029e+00, -2.849849902355308e+00, -2.550250273536410e+00, -2.183971019896485e+00, -1.765879666439372e+00, -1.329217578196886e+00, -9.081179089602194e-01, -6.303201523046452e-01, -5.505394355436979e-01, -4.575513727705672e-01, -3.353463260550939e-01, -2.166321368756925e-01, -1.318920514867749e-01, -8.787891087401636e-02, -5.167302183966983e-02, -3.151291616726733e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


